          d="M52.1893 31.9077C51.9894 31.9077 51.6894 31.8078 51.4895 31.6078L48.4901 28.7084C48.0902 28.3085 48.0902 27.7087 48.4901 27.3087C48.89 26.9088 49.4899 26.9088 49.8898 27.3087L52.8892 30.2081C53.2891 30.608 53.2891 31.2079 52.8892 31.6078C52.6892 31.8078 52.4893 31.9077 52.1893 31.9077ZM44.591 35.8069H44.291C43.7911 35.7069 43.4912 35.1071 43.5912 34.6072L45.6907 26.8088C45.7907 26.309 46.3906 26.009 46.8905 26.109C47.3904 26.209 47.6903 26.8088 47.5903 27.3087L45.5907 35.1071C45.3908 35.507 44.9909 35.8069 44.591 35.8069ZM24.8952 40.3059H8.89868C6.4992 40.3059 4.59961 38.4063 4.59961 36.0069C4.59961 33.6074 6.4992 31.7078 8.89868 31.7078H24.8952C27.2947 31.7078 29.1943 33.6074 29.1943 36.0069C29.1943 38.4063 27.2947 40.3059 24.8952 40.3059ZM8.89868 33.7074C7.69894 33.7074 6.59918 34.8071 6.59918 36.0069C6.59918 37.2066 7.69894 38.3064 8.89868 38.3064H24.8952C26.095 38.3064 27.1947 37.2066 27.1947 36.0069C27.1947 34.8071 26.095 33.7074 24.8952 33.7074H8.89868Z"
